pub fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    assert!(n > 0, "n must be > 0");
    assert!(j < m, "column index j out of bounds");

    // Optional shape checks (keeps behavior well-defined if caller lies about m/n)
    assert!(
        input.len() == n,
        "input row count does not match n (expected {n}, got {})",
        input.len()
    );
    for (r, row) in input.iter().enumerate() {
        assert!(
            row.len() == m,
            "row {r} length does not match m (expected {m}, got {})",
            row.len()
        );
    }

    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        col.push(input[i][j]);
    }
    col
}

pub fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    assert!(n > 0, "n must be > 0");

    // Optional shape checks
    assert!(
        input.len() == n,
        "input row count does not match n (expected {n}, got {})",
        input.len()
    );
    for (r, row) in input.iter().enumerate() {
        assert!(
            row.len() == m,
            "row {r} length does not match m (expected {m}, got {})",
            row.len()
        );
    }

    let mut result: Vec<Vec<i8>> = Vec::with_capacity(m);
    for j in 0..m {
        result.push(get_column(&input, j, m, n));
    }
    result
}